INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486667-ae325', 'stk-avgeek', 'AE 325', 'info', '{"desc": "جودة المقرر بشكل عام:\nمن اهم مواضيع التخصص وفرع يعتبر اساسي.\nالمواضيع التي يغطيها المقرر :\nالمقرر يتكلم بشكل أساسي عن compressible fluid flow ومدى تأثره بعدة عوامل منها:\nArea\nchange (nozzles and diffusers), friction and heat interaction (Fanno, Rayleigh, and\nisothermal flows), combustion waves (deflagration, explosion, and detonation waves),\nnormal and oblique shock waves, expansion fans (Prandtl-Meyer waves)\n\nالكتاب المستخدم للمقرر:\nJames E.A. John and Theo G. Keith, Gas Dynamics, 3\n\nrd Ed., Pearson\n\nHigher Education, 2006.\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nيحتوي المقرر على العديد من الامثلة والاسئلة في نهاية كل شابتر , الأمثلة كافية لفهم الكونسبت جيدا.\nمدى فائدته في الناحية التطبيقية:\nلاشك مهم جدا واهم فائدة Estimate the lift and drag for basic aerodynamic shapes in compressible, inviscid flows", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae-325-gas-dynamics-i/120798/2", "user": "AvGeek", "ts": 1516746404000, "tid": 120798, "pn": 2}}', 1516746404000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522057-ae325', 'stk-user10610', 'AE 325', 'info', '{"desc": "AE325-192\nجودة المقرر بشكل عام:\nجدا مهم , ويعتبر من أحجار الأساس في التخصص. هو العلامة الفارقة بينك وبين طالب الميكانيكال , بحيث أنك تتعمق زيادة في الموائع والأشياء هذي. أقرب مادة لها هي الثيرمو عند الميكانيكال . الكتاب مرفق معه جداول وعن حل أي سؤال في الغالب أنك بتستخدم الجداول هذي. مواضيع الكورس بشكل عام عندك هوا داخل nozzle ويعطيك صفات الهواء السرعة والضغط ووو ويطلب منك وش بيصير في مخرج الnozzel , وتتغير المتطلبات كل ما تقدمت في الكورس ولكن تبقى نفس الفكرة العامة.\nــــــــــــــــــــــــــــــــــــــــــــ\nالمادة في العادة يدرسها الدكتور سلمان الفيفي ولكن ممكن يتغير في المستقبل\nطريقة المذاكرة:\nسلايدات الدكتور والشرح في الكلاس جدا كافية انه يكون عندك فكرة عامة عن الموضوع, لو تحب تتعمق وتقرا تفاصيل الكتاب جدا جيد. السلايدات والشرح مفيدة للفكرة للعامة ولكن لابد من أنك تحل بنفسك وتشوف وش يصير معك خلال الحل , الفكرة اللي اخذتها من السلايدات تقول لك لابد ان درجة الحرارة ترتفع بشكل كثير فاذا حليت ونقصت درجة الحرارة هنا تعرف أن ففيه مشكلة ( الخلاصة اذا فيه كوز مذاكرة السلايدات فقط ما بتكفيك)\nوزي ما قلنا لازم تعرف تتعامل مع الجداول لانها مستمره معك إلى أخر كلاس في السمستر.\nالواجب :\nيعلمك وش نوع أسئلة الكوز والميجر , لذلك لو حليتها بنفسك ما بتنصدم في الميجر ما بيجيك شي خارج عن المألوف , والمدة أسبوع في الغالب للتسليم .\nالمياجر:\nواحد ورقي والثاني أونلاين خيارات ( عشان أزمة كورونا) كلهم قريب من مستوى الواجب لكن فيه سؤال يجيك طوييل عليه 30 درجة وسؤال ديرايفيشن\n( أول اسبوعين في الكورس كلها ديرايفيشن لثلاث معادلات energy,momentum,mass conservation ) الكلاس ممل بشكل موب طبيعي وقتها والدكتور مجتهد مره يعني يشرح لك حبه حبه , ولكن بعدها أي سؤال بيمر عليك في الكورس في الغالب بتستخدم وحده منهم عشان تحل لذلك مهم انك تحل أسئلة عشان تعرف أي وحده تستخدم.\n- أيضا الأمثلة المحلولة في الكتاب مهم تسلم عليها 👋 لان جانا سؤال في الميجر ما قد حلينا زيه في الواجب أو الكلاس ولكن قال لنا محلول في الكتاب.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae-325-gas-dynamics-i/120798/3", "user": "user10610", "ts": 1589509187000, "tid": 120798, "pn": 3}}', 1589509187000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-momanso-ae325', 'stk-momanso', 'AE 325', 'doc', '{"docs": [{"id": "stk-dr-f115284", "n": "Dr. Farooq Saeed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بالنسبة للدكتور فاروق أنا أخذت معه الـGas Dynamics (AE325)\n\nالتحضير : يحضر بداية كل كلاس\nطريقة الشرح: يستخدم السلايدات وشرحه ممل جداً ويجيب النوم ويستخدم السبورة بشكل عشوائي غير منظم\n\nالكويزات : يعطي 5 كويزات في السمستر وتكون مفاجئة ومستواها متوسطة إلى سهلة للي يفهم عليه\n\nالمياجر: سهلة للي يفهم معاه في الكلاس ويذاكر … لأنها مشابهة للأمثلة\nالفاينلات : الفاينل يجيبه شامل لجميع المنهج وأسئلة معقولة\nالصوت : منخفض جداً جداً … وفي بعض الأحيان يكاد لا ينسمع\nالقريد النهائي: D+\nإضافات : الدكتور طيب في تعامله مع الطلاب ومتسامح نوعاً ما … بس مشكلته إنه مايوضح إيش المطلوب يعني مثلاً ما يحدد موعد نهائي في بداية السمستر لتسليم المشاريع\nأتوقع الدكتور كان ممتاز في السابق على حسب كلام الطلاب …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p977665-ae325", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-farooq-saeed/115284/2", "user": "MoManSo", "ts": 1328036000000, "tid": 115284, "pn": 2}}]}', 1328036000000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
